-- PT113-S2-Q12. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT113-S2-Q12$batch11$ AND q.stimulus=$batch11$Rosen: One cannot prepare a good meal from bad food, produce good food from bad soil, maintain good soil without good farming, or have good farming without a culture that places value on the proper maintenance of all its natural resources so that needed supplies are always available.$batch11$ AND q.prompt=$batch11$Which one of the following can be properly inferred from Rosen's statement?$batch11$ AND q.correct_choice=$batch11$A$batch11$) THEN RAISE EXCEPTION 'Question changed: PT113-S2-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT113-S2-Q12$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT113-S2-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT113-S2-Q12$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Good meal → good food. Good food → good soil. Good soil → good farming. Good farming → a culture that values maintaining natural resources.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Rosen gives a chain of requirements. Link it: good meal → good food → good soil → good farming → the right culture. So a good meal requires good soil, which is a natural condition, and the right culture, which is a cultural condition.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Good meals depend on both natural and cultural conditions.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT113-S2-Q12$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Follow the chain. Good meals need good soil (natural) and, further down, a culture that values resources (cultural).$batch11$), ($batch11$B$batch11$, $batch11$Rosen says good farming requires the right culture. Nothing says maintaining natural resources requires good farming.$batch11$), ($batch11$C$batch11$, $batch11$Good soil requires good farming. This says good farming requires good soil.$batch11$), ($batch11$D$batch11$, $batch11$Good culture is required for good meals, not enough for them.$batch11$), ($batch11$E$batch11$, $batch11$Bad food isn't traced back to a single cause. Good soil is required for good food, but food can go bad in other ways.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT113-S2-Q12$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
